begin
 update public.td_workspaces set state=jsonb_set(jsonb_set(state,'{players}',(state->'players')||(fixture->'players')),'{tournaments}',(state->'tournaments')||(fixture->'tournaments')),version=version+1 where owner_id=owner;
end $test$;
set local role authenticated;
do $test$
declare r public.td_workspaces; r2 public.td_workspaces; e jsonb; t jsonb; p jsonb; request uuid:=gen_random_uuid(); deadline bigint; n bigint; s jsonb; before_state jsonb;
begin
 r:=public.td_remote_elimination('remote-validation-event','remote-validation-entry-2',request,'start');
 select value into t from jsonb_array_elements(r.state->'tournaments') where value->>'id'='remote-validation-event';e:=t->'entries'->1;p:=e->'pendingElimination';deadline:=(p->>'expiresAt')::bigint;
 assert deadline-(p->>'requestedAt')::bigint=5000,'Window must be exactly five seconds';
 assert e->>'eliminatedAt' is null and e->>'place' is null and e->>'seat'='2','Pending entry lost its status/seat';
 r2:=public.td_remote_elimination('remote-validation-event','remote-validation-entry-2',request,'start');assert r2.version=r.version,'Duplicate start changed state';
 s:=td_internal.finalize_remote(r.state,deadline-1);assert s=r.state,'Finalized early';s:=td_internal.finalize_remote(r.state,deadline);
 select value into t from jsonb_array_elements(s->'tournaments') where value->>'id'='remote-validation-event';assert t#>>'{entries,1,place}'='4','Wrong finishing place';assert t#>>'{entries,1,table}' is null,'Final seat not released';assert td_internal.finalize_remote(s,deadline+9999)=s,'Duplicate finalization';
 begin
  perform public.td_save_workspace(r.version,jsonb_set(r.state,array['tournaments',(jsonb_array_length(r.state->'tournaments')-1)::text,'entries','1','seat'],'3'::jsonb));raise exception 'Seat mutation was accepted';
 exception when others then if sqlerrm not like '%reserved%' then raise;end if;end;
 begin
  perform public.td_save_workspace(r.version,r.state#-array['tournaments',(jsonb_array_length(r.state->'tournaments')-1)::text,'entries','1','pendingElimination']);raise exception 'Pending deletion was accepted';
 exception when others then if sqlerrm not like '%managed by the server%' then raise;end if;end;
 r:=public.td_remote_elimination('remote-validation-event','remote-validation-entry-2',request,'undo');select value into t from jsonb_array_elements(r.state->'tournaments') where value->>'id'='remote-validation-event';assert t#>'{entries,1,pendingElimination}' is null,'Undo failed';assert t#>>'{entries,1,seat}'='2','Undo lost seat';assert t#>>'{entries,1,place}' is null,'Undo assigned a place';
 r2:=public.td_remote_elimination('remote-validation-event','remote-validation-entry-2',request,'start');assert r2.version=r.version,'Canceled request restarted';
 perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 begin perform public.td_remote_elimination('remote-validation-event','remote-validation-entry-2',gen_random_uuid(),'start');raise exception 'Cross-owner request accepted';exception when others then if sqlerrm not like '%Load your tournament account first%' then raise;end if;end;
end $test$;
reset role;
-- Exercise the actual worker update/trigger path with an expired synthetic request.
select set_config('request.jwt.claim.sub',(select owner_id::text from public.td_workspaces limit 1),true);
do $test$
declare r public.td_workspaces; s jsonb; idx text; e jsonb; n bigint;
begin
 r:=public.td_remote_elimination('remote-validation-event','remote-validation-entry-2',gen_random_uuid(),'start');
 select (ordinality-1)::text into idx from jsonb_array_elements(r.state->'tournaments') with ordinality where value->>'id'='remote-validation-event';
 perform set_config('td.remote_write','on',true);
 update public.td_workspaces set state=jsonb_set(state,array['tournaments',idx,'entries','1','pendingElimination','expiresAt'],to_jsonb(floor(extract(epoch from clock_timestamp())*1000)::bigint-1)) where owner_id=auth.uid();
 perform set_config('td.remote_write','off',true);
 n:=td_internal.finalize_remote_eliminations();assert n=1,'Worker did not finalize the queued document';
 select state into s from public.td_workspaces where owner_id=auth.uid();e:=s#>array['tournaments',idx,'entries','1'];assert e->>'place'='4','Worker finish incorrect';assert e->>'table' is null,'Worker left seat occupied';assert e->'pendingElimination' is null,'Worker left pending metadata';assert td_internal.finalize_remote_eliminations()=0,'Worker finalized twice';
end $test$;
rollback;
select 'PASS: server deadlines, idempotence, seat reservation, Undo, owner isolation; all fixture records rolled back' as result;
